import{_ as p,o as e,c as s,a2 as t}from"./chunks/framework.D66Xq0Kv.js";const b=JSON.parse('{"title":"线路中电容反射","description":"","frontmatter":{},"headers":[],"relativePath":"notes/《信号完整性》学习笔记/19-线路中电容反射.md","filePath":"notes/《信号完整性》学习笔记/19-线路中电容反射.md","lastUpdated":1794204395000}'),r={name:"notes/《信号完整性》学习笔记/19-线路中电容反射.md"};function n(c,a,o,d,l,i){return e(),s("div",null,[...a[0]||(a[0]=[t('<h1 id="线路中电容反射" tabindex="-1">线路中电容反射 <a class="header-anchor" href="#线路中电容反射" aria-label="Permalink to &quot;线路中电容反射&quot;">​</a></h1><h2 id="一链路中间电容的互连结构" tabindex="-1">一、链路中间电容的互连结构 <a class="header-anchor" href="#一链路中间电容的互连结构" aria-label="Permalink to &quot;一、链路中间电容的互连结构&quot;">​</a></h2><p>电容处于线路中间的时候，它是什么样的反射特性？它对于整个链路上各个点上的信号会产生哪些影响？</p><p>驱动器出来，源端这个地方是 50 Ω；不考虑驱动器这一端信号的反射，只考虑电容的反射。信号经过一段传输线，特性阻抗 50 Ω，延迟是 1 ns；中间是一个电容、容性负载；因为电容在链路的中间，后面还有一段小的传输线，阻抗 50 Ω，延迟 500 ps。末端阻抗非常高，接近于开路。</p><p><img src="https://cdn.nlark.com/yuque/0/2026/svg/2113993/1794183760294-462d1e2b-9dd4-401c-b13a-0b60d00b55e7.svg" alt="链路中间电容的互连结构"></p><h2 id="二电容位置的瞬时阻抗" tabindex="-1">二、电容位置的瞬时阻抗 <a class="header-anchor" href="#二电容位置的瞬时阻抗" aria-label="Permalink to &quot;二、电容位置的瞬时阻抗&quot;">​</a></h2><p>跟着信号向前走，信号沿着传输线到达电容这个位置的时候，向前看，看到的是一个电容和一段 50 Ω 传输线。</p><p>信号入射到这一点的这一瞬间，它感受到的阻抗是电容和传输线这两个阻抗值的并联。传输线是 50 Ω，这是固定的；电容呢？</p><p>电容充电的时候，电压变化特性、电流变化特性的曲线都是一直在变化的，成指数型变化。</p><p><img src="https://cdn.nlark.com/yuque/0/2026/svg/2113993/1794192281900-e749a034-0e4e-46a7-9bc8-9aefabb1bebb.svg" alt="电容充电时的电压与电流变化曲线"></p><p>所以说电容的阻抗也是时刻都在变化的：</p><p>信号到这的一瞬间，阻抗是零，接近短路；随着时间的推移，电容的阻抗越来越高，几个 Ω、十几个 Ω、二十几个 Ω，不断在变。</p><p><img src="https://cdn.nlark.com/yuque/0/2026/svg/2113993/1794192282284-1b5386b6-373d-43ef-a525-469e8bd61a3e.svg" alt="电容阻抗随时间变化的曲线"></p><p>信号所感受到的阻抗是这两个阻抗并联，也在不断地变化。 对于电容来说，不能简单地按照理想的纯阻性负载那样去计算它的反射，因为这里类似于一个积分过程一样，它都是时刻在变的。 不管怎么说，信号入射的一瞬间，这个阻抗肯定比较低，因为电容的阻抗在这一瞬间是零。 但是无论怎么说，并联之后的阻抗是降低的，信号在这一点肯定会发生一个负反射。</p><h2 id="三往返反射与塌陷的形成" tabindex="-1">三、往返反射与塌陷的形成 <a class="header-anchor" href="#三往返反射与塌陷的形成" aria-label="Permalink to &quot;三、往返反射与塌陷的形成&quot;">​</a></h2><p>信号沿着后面这一小段传输线往前跑，跑到末端之后，发现一个非常高的阻抗，于是发生反射。</p><p>反射信号回到电容这个位置，往左一看，是 50 Ω 和电容并联，这里又会发生一个负反射。</p><p>当信号刚刚入射进来的时候，看到的是电容的阻抗特性，那一瞬间它的阻抗是零，但是随着时间推移，阻抗不断变化。</p><p>电容会在这个传输线入口的位置引起一个塌陷，就像叠加了一个负脉冲一样；右边的信号也必然会产生一个塌陷。</p><p>信号在这里产生的负反射沿传输线往末端跑，到末端遇到高阻抗，负跳变的反射幅度进一步增加，末端就会叠加出一个幅度噪声、一个回勾。这个回勾是幅度上的塌陷。</p><h2 id="四传输线入口波形的形成" tabindex="-1">四、传输线入口波形的形成 <a class="header-anchor" href="#四传输线入口波形的形成" aria-label="Permalink to &quot;四、传输线入口波形的形成&quot;">​</a></h2><p>这个波形到底会是什么样子？</p><p>当上升时间是零的时候，驱动器那一端是 Vin 的波形，末端开路那一端是 Vout 的波形，中间电容负载那个位置也有一条波形。分析这几个波形，就能很直观地理解反射这个过程到底是什么样子的。</p><p>传输线入口这个位置，它的波形会是什么样子的？</p><p>信号过来之后经过 1 ns 到达电容这个位置。信号到达之后，电容与 50 Ω 传输线并联，阻抗比较低，它会产生一个负反射。</p><p>对于上升时间为零的理想方波来说，电容对它的反射一下给它拉到 0。</p><p>这个瞬间产生的反射，经过 1 ns 的延迟回到传输线入射的端点：去 1 ns，回 1 ns。信号经过 2 ns 之后，在传输线入口会看到一个很深的塌陷。这是第一次信号入射的时候，电容产生的反射。</p><p><img src="https://cdn.nlark.com/yuque/0/2026/svg/2113993/1794204145121-453008ef-e6b7-4d62-a7b6-edb08af4cc00.svg" alt="传输线入口的波形"></p><p>跟着信号往前走，再经过 500 ps 到达末端。末端是高阻抗，发生全反射，反射信号往回走，又经过 1 ns 回到入射端，入射端上升，达到满幅度。</p><p>反射信号经过 500 ps 回到电容这个位置，它看到的是电容和传输线的并联。对于理想的方波信号来说，这里又是一个非常大的负反射；如果信号上升时间是零，会一下塌到零，像一个非常大的负脉冲一样。但是信号经过了这个电容之后，信号的边沿会变缓，有了一定的上升时间，这个时候产生的负反射不会那么大，塌陷会变小。</p><p>这个负反射沿传输线走到末端，经过 500 ps 遇到又一个高阻抗，正反射让这个负跳变的噪声进一步增加，是同方向的。回来又经过 500 ps，一去一回刚好 1 ns，在电容这个位置又产生了一个塌陷。这个塌陷是信号在电容位置反射、到末端再反射，500 ps 到末端、再加 500 ps 回来产生的。</p><p>传输线入口这个位置产生这样的波形，原因就在这儿。</p><p>再往下一步，为什么又是向上的一个毛刺？</p><p>继续跟着这个信号走：负的毛刺回来，到电容这里又产生一个负反射，本来是一个负的毛刺，经过负反射之后，它变成一个正跳变的毛刺；正跳变毛刺沿着传输线往末端跑，跑到末端之后再回来，这一来一回是 1 ns，在这里又变出来一个正跳变的毛刺。</p><h2 id="五末端波形的形成" tabindex="-1">五、末端波形的形成 <a class="header-anchor" href="#五末端波形的形成" aria-label="Permalink to &quot;五、末端波形的形成&quot;">​</a></h2><p>接着看末端那个波形。</p><p>信号经过 1 ns、再经过 500 ps，1.5 ns 的时候到达末端。到达末端之后反射，经过 500 ps 回到电容这个位置，在那里又发生一次负反射。这个塌陷从电容这个位置往末端走，经过 500 ps 到达末端，一去一回是两个 500 ps、一共 1 ns。所以 1.5 ns 信号到达末端，再经过两个 500 ps，电容反射回来的塌陷在这里出现。</p><p><img src="https://cdn.nlark.com/yuque/0/2026/svg/2113993/1794203695400-ab155dd0-9df5-4582-82b5-6ce4c9fb6fca.svg" alt="末端的波形"></p><p>这个塌陷，在末端波形上是最先出现的那一个，它从末端反射回来，叠加到电容这个位置的波形上。它本来是一个负跳变的塌陷，在这里又是一个负反射，就变成了正跳变的毛刺。正跳变的毛刺沿着传输线往前跑，跑到末端它再反射，变成进一步的大幅度正跳变，这就是末端波形上第一个向上的毛刺。</p><p>不断来回反射、叠加，就形成了这样一种波形。</p><h2 id="六链路中间节点波形与多电容负载" tabindex="-1">六、链路中间节点波形与多电容负载 <a class="header-anchor" href="#六链路中间节点波形与多电容负载" aria-label="Permalink to &quot;六、链路中间节点波形与多电容负载&quot;">​</a></h2><p>最后补充一点，从链路中间这一点再看一下波形，印证一下是不是这么回事。这个波形是两段传输线中间那一点的波形。</p><p>信号经过 1 ns 到这一点，又经过 500 ps 到末端，反射回来就经过了 1 ns，它会跳变到满幅度。先反射回来的这个信号，在电容这里发生一个负反射；负反射经过 500 ps 传到末端，在末端又反射，负跳变幅度更加增大；再经过 500 ps 到这一点。也就是说，一去一回 1 ns，在这个位置出现一个塌陷。</p><p><img src="https://cdn.nlark.com/yuque/0/2026/svg/2113993/1794203695779-959afd58-24a9-4c18-acf7-38589ae591b2.svg" alt="链路中间电容位置的波形"></p><h2 id="七塌陷对时序的影响与工程判断" tabindex="-1">七、塌陷对时序的影响与工程判断 <a class="header-anchor" href="#七塌陷对时序的影响与工程判断" aria-label="Permalink to &quot;七、塌陷对时序的影响与工程判断&quot;">​</a></h2><p>前面几个位置的波形，最先出现的都是一个比较大的塌陷。</p><p>塌陷一旦过大的时候，时序的余量就不够了，时间窗口宽度就不够，DDR 结构就可能会出现问题。</p><h2 id="八塌陷幅度与上升时间容性负载的关系" tabindex="-1">八、塌陷幅度与上升时间、容性负载的关系 <a class="header-anchor" href="#八塌陷幅度与上升时间容性负载的关系" aria-label="Permalink to &quot;八、塌陷幅度与上升时间、容性负载的关系&quot;">​</a></h2><p>接下来还有一个问题：波形上的这些回勾、塌陷，它的大小跟什么有关？</p><p>还是跟上升时间有关。</p><p>上升时间越小、边沿越陡峭，回勾就会越大；上升时间进一步的变长，它就更小。</p><p><img src="https://cdn.nlark.com/yuque/0/2026/svg/2113993/1794201989246-5eb81efe-d64d-495e-9d0f-79970e690111.svg" alt="塌陷随上升时间的变化"></p><p>另外还跟容性负载有关。红色的是 2 pF 的，容性负载比较小，塌陷就比较小；4 pF 的蓝色线塌陷更大，8 pF 就更大。也就是说容性负载越大、电容越大，反射就越厉害，塌陷就会越厉害。</p><p><img src="https://cdn.nlark.com/yuque/0/2026/svg/2113993/1794142177232-99c8f64a-116d-4459-9f30-cbb94cd20251.svg" alt="塌陷随容性负载的变化"></p><p>这些东西，数值计算并不重要，关键是了解电容这个负载在链路中间的时候，整个互连结构是怎么工作的、中间到底发生了一些什么。能有一种比较直观的感受，这些对于工程才是比较重要的。</p>',55)])])}const u=p(r,[["render",n]]);export{b as __pageData,u as default};
